int MqttProps_ShutDown(void)
{
    int ret = MQTT_CODE_SUCCESS;
#if !defined(WOLFMQTT_DYN_PROP) && defined(WOLFMQTT_MULTITHREAD)
    clientPropStack_lockInit--;
    if (clientPropStack_lockInit == 0) {
        ret = wm_SemFree(&clientPropStack_lock);
    }
#endif
    return ret;
